import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem78 preserva identidade operação e idempotência sem transformar RAM Boost em física',()=>{for(const [id,titulo] of [['GPORGqPOixfgh38bVrXX','Smartphone Motorola Edge 70 Pro 5g - 256gb 24gb (12gb Ram+12gb Ram Boost), 4 Câmeras De 50mp, Tela 1.5k Extreme Amoled 144hz, Bateria 6500 Mah, Ip68/ip69 - Azul Escuro'],['GQiP9vBIhECa4I5CuzkB','Tênis Flyer Runner Mesh Bdp Puma']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/24 GB.*física|quatro câmeras traseiras|autenticidade garantida|amortecimento/i);}});
